//! Golden-corpus tests for the motion controller.
//!
//! `test_data/motion_profiles.json` is exact ground truth generated by
//! `lean/MotionTestData.lean`; the document schema is `docs/motion_control.md` §6.3 and
//! the checks are §6.4. The polynomial layer is generic over the field, so the expected
//! profiles, `stretch` and `synchronize` are checked over `robot_golden::Ratio` with
//! `==`. Only the optimal and general planners, which need `sqrt`/`cbrt`, are compared in
//! `f64`, with the corpus tolerance `1e-12 * max(1, |expected|)`.

use robot_golden::{Ratio, entries, name, numeral, numeral_at};
use robot_motion::{
    Limits, MAX_PHASES, PlanError, PlanKind, Profile, Segment, State, plan_general,
    plan_rest_conservative, plan_rest_to_rest, synchronize,
};
use serde_json::Value;

const DOCUMENT: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../test_data/motion_profiles.json"
));

fn document() -> Value {
    serde_json::from_str(DOCUMENT).expect("motion_profiles.json is valid JSON")
}

// ---------------------------------------------------------------------------
// Parsing the corpus.
// ---------------------------------------------------------------------------

fn read_state(value: &Value) -> State<Ratio> {
    State::new(
        numeral_at(value, "q").unwrap(),
        numeral_at(value, "v").unwrap(),
        numeral_at(value, "a").unwrap(),
    )
}

fn read_state_f64(value: &Value) -> State<f64> {
    let state = read_state(value);
    State::new(state.q.to_f64(), state.v.to_f64(), state.a.to_f64())
}

fn read_segments(value: &Value) -> Vec<Segment<Ratio>> {
    value
        .as_array()
        .unwrap_or_else(|| panic!("expected a segment array, found {value}"))
        .iter()
        .map(|segment| Segment {
            dur: numeral_at(segment, "duration").unwrap(),
            jerk: numeral_at(segment, "jerk").unwrap(),
        })
        .collect()
}

fn read_limits_exact(value: &Value) -> Limits<Ratio> {
    Limits::new(
        numeral_at(value, "v_max").unwrap(),
        numeral_at(value, "a_max").unwrap(),
        numeral_at(value, "j_max").unwrap(),
    )
    .unwrap()
}

fn read_limits_f64(value: &Value) -> Limits<f64> {
    Limits::new(
        numeral_at(value, "v_max").unwrap().to_f64(),
        numeral_at(value, "a_max").unwrap().to_f64(),
        numeral_at(value, "j_max").unwrap().to_f64(),
    )
    .unwrap()
}

fn expected_profile(case: &Value) -> Profile<Ratio> {
    let start = read_state(case.get("start").unwrap());
    let expected = case.get("expected").unwrap();
    let segments = read_segments(expected.get("segments").unwrap());
    Profile::from_parts(start, &segments).unwrap()
}

fn plan_kind(text: &str) -> PlanKind {
    match text {
        "zero_motion" => PlanKind::ZeroMotion,
        "conservative" => PlanKind::Conservative,
        "cruise" => PlanKind::Cruise,
        "peak_no_cruise" => PlanKind::PeakNoCruise,
        "triangular" => PlanKind::Triangular,
        "general" => PlanKind::General,
        other => panic!("unknown PlanKind {other:?}"),
    }
}

fn abs(value: Ratio) -> Ratio {
    if value < Ratio::ZERO { -value } else { value }
}

fn max_pair(a: Ratio, b: Ratio) -> Ratio {
    if a < b { b } else { a }
}

/// Exact maxima of `|v|`, `|a|` and `|j|` over the profile.
///
/// Acceleration is linear on a segment, so its extremes are the endpoints; velocity is
/// quadratic, so its extremes are the endpoints or the vertex when it lies strictly
/// inside the segment. This is the complete check, not a sample.
fn maxima(profile: &Profile<Ratio>) -> (Ratio, Ratio, Ratio) {
    let two = Ratio::integer(2);
    let mut speed = max_pair(abs(profile.start().v), abs(profile.end().v));
    let mut accel = max_pair(abs(profile.start().a), abs(profile.end().a));
    let mut jerk = Ratio::ZERO;
    for (i, segment) in profile.segments().iter().enumerate() {
        let entry = profile.phase_start(i).unwrap();
        let exit = profile.phase_start(i + 1).unwrap_or_else(|| profile.end());
        jerk = max_pair(jerk, abs(segment.jerk));
        accel = max_pair(accel, abs(entry.a));
        accel = max_pair(accel, abs(exit.a));
        speed = max_pair(speed, abs(exit.v));
        if !segment.jerk.is_zero() {
            let vertex = -entry.a / segment.jerk;
            if vertex > Ratio::ZERO && vertex < segment.dur {
                let velocity = entry.v + entry.a * vertex + segment.jerk * vertex * vertex / two;
                speed = max_pair(speed, abs(velocity));
            }
        }
    }
    (speed, accel, jerk)
}

// ---------------------------------------------------------------------------
// Exact expected-profile checks, common to every accepted case.
// ---------------------------------------------------------------------------

#[track_caller]
fn check_expected_profile(case: &Value) {
    let label = name(case);
    let expected = case.get("expected").unwrap();
    let profile = expected_profile(case);

    assert_eq!(
        profile.start(),
        read_state(case.get("start").unwrap()),
        "{label}: start state"
    );
    assert_eq!(
        profile.end(),
        read_state(case.get("end").unwrap()),
        "{label}: end state"
    );
    assert_eq!(
        profile.total_time(),
        numeral_at(expected, "total_time").unwrap(),
        "{label}: total time"
    );

    let phase_starts = expected
        .get("phase_starts")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("{label}: missing phase_starts"));
    assert_eq!(
        phase_starts.len(),
        profile.segments().len(),
        "{label}: one phase start per segment"
    );
    for (i, entry) in phase_starts.iter().enumerate() {
        assert_eq!(
            profile.phase_start(i),
            Some(read_state(entry)),
            "{label}: phase start {i}"
        );
    }

    for sample in expected
        .get("samples")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("{label}: missing samples"))
    {
        let t = numeral_at(sample, "t").unwrap();
        let got = profile.eval(t);
        assert_eq!(
            got.q,
            numeral_at(sample, "q").unwrap(),
            "{label}: q at t={t:?}"
        );
        assert_eq!(
            got.v,
            numeral_at(sample, "v").unwrap(),
            "{label}: v at t={t:?}"
        );
        assert_eq!(
            got.a,
            numeral_at(sample, "a").unwrap(),
            "{label}: a at t={t:?}"
        );
    }

    let (speed, accel, jerk) = maxima(&profile);
    assert_eq!(
        speed,
        numeral_at(expected, "max_speed").unwrap(),
        "{label}: max_speed"
    );
    assert_eq!(
        accel,
        numeral_at(expected, "max_accel").unwrap(),
        "{label}: max_accel"
    );
    assert_eq!(
        jerk,
        numeral_at(expected, "max_jerk").unwrap(),
        "{label}: max_jerk"
    );

    // Rest-to-rest cases start and finish at rest. The general case is the deliberate
    // exception: it starts and ends moving.
    if case.get("mode").and_then(Value::as_str) != Some("general") {
        let start = profile.start();
        let end = profile.end();
        assert_eq!(
            (start.v, start.a, end.v, end.a),
            (Ratio::ZERO, Ratio::ZERO, Ratio::ZERO, Ratio::ZERO),
            "{label}: rest boundaries"
        );
    }
}

// ---------------------------------------------------------------------------
// Tolerance helpers for the f64 planners.
// ---------------------------------------------------------------------------

#[track_caller]
fn close(label: &str, field: &str, actual: f64, expected: Ratio) {
    let expected = expected.to_f64();
    let tolerance = 1e-12 * expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tolerance,
        "{label}: {field}: got {actual:.17e}, expected {expected:.17e} \
         (tolerance {tolerance:.3e})"
    );
}

#[track_caller]
fn close_state(label: &str, what: &str, actual: State<f64>, expected: State<Ratio>) {
    close(label, &format!("{what}.q"), actual.q, expected.q);
    close(label, &format!("{what}.v"), actual.v, expected.v);
    close(label, &format!("{what}.a"), actual.a, expected.a);
}

fn check_f64_samples(label: &str, profile: &Profile<f64>, expected: &Value) {
    let samples = expected
        .get("samples")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("{label}: missing samples"));
    for sample in samples {
        let t = numeral_at(sample, "t").unwrap().to_f64();
        let got = profile.eval(t);
        let want = read_state(sample);
        close_state(label, &format!("sample t={t:.17e}"), got, want);
    }
}

// ---------------------------------------------------------------------------
// Per-mode planner checks.
// ---------------------------------------------------------------------------

#[track_caller]
fn check_conservative_case(case: &Value) {
    let label = name(case);
    let start = read_state(case.get("start").unwrap());
    let end = read_state(case.get("end").unwrap());
    let limits = read_limits_exact(case.get("limits").unwrap());
    let planned = plan_rest_conservative::<Ratio>(start.q, end.q, limits)
        .unwrap_or_else(|error| panic!("{label}: conservative planner failed: {error:?}"));
    let expected = case.get("expected").unwrap();

    assert_eq!(planned.kind(), PlanKind::Conservative, "{label}: kind");
    assert_eq!(planned.start(), start, "{label}: start state");
    assert_eq!(planned.end(), end, "{label}: end state");
    assert_eq!(
        planned.total_time(),
        numeral_at(expected, "total_time").unwrap(),
        "{label}: total time"
    );
    assert_eq!(planned.segments().len(), 7, "{label}: 7-slot form");

    let expected_segments = read_segments(expected.get("segments").unwrap());
    assert_eq!(
        planned.segments(),
        expected_segments.as_slice(),
        "{label}: segments"
    );

    let phase_starts = expected.get("phase_starts").unwrap().as_array().unwrap();
    assert_eq!(phase_starts.len(), planned.segments().len());
    for (i, entry) in phase_starts.iter().enumerate() {
        assert_eq!(
            planned.phase_start(i),
            Some(read_state(entry)),
            "{label}: phase start {i}"
        );
    }

    // The produced profile is the expected one, so its trajectory is the corpus
    // trajectory; evaluate it anyway so a planner bug cannot hide in the fold.
    for sample in expected.get("samples").unwrap().as_array().unwrap() {
        let t = numeral_at(sample, "t").unwrap();
        let got = planned.eval(t);
        assert_eq!(
            got.q,
            numeral_at(sample, "q").unwrap(),
            "{label}: q at {t:?}"
        );
        assert_eq!(
            got.v,
            numeral_at(sample, "v").unwrap(),
            "{label}: v at {t:?}"
        );
        assert_eq!(
            got.a,
            numeral_at(sample, "a").unwrap(),
            "{label}: a at {t:?}"
        );
    }
}

#[track_caller]
fn check_optimal_case(case: &Value) {
    let label = name(case);
    let start = read_state(case.get("start").unwrap());
    let end = read_state(case.get("end").unwrap());
    let limits = read_limits_f64(case.get("limits").unwrap());
    let planned = plan_rest_to_rest(start.q.to_f64(), end.q.to_f64(), limits)
        .unwrap_or_else(|error| panic!("{label}: optimal planner failed: {error:?}"));
    let expected = case.get("expected").unwrap();

    // The trajectory comparison applies to every optimal case, threshold or not.
    check_f64_samples(label, &planned, expected);

    // At an exact case boundary the f64 planner may legitimately select the adjacent
    // case; the corpus marks those cases `threshold` and only the trajectory is compared.
    if case
        .get("threshold")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| panic!("{label}: missing threshold flag"))
    {
        return;
    }

    assert_eq!(
        planned.kind(),
        plan_kind(case.get("kind").unwrap().as_str().unwrap()),
        "{label}: kind"
    );
    close(
        label,
        "total_time",
        planned.total_time(),
        numeral_at(expected, "total_time").unwrap(),
    );

    let expected_segments = read_segments(expected.get("segments").unwrap());
    assert_eq!(
        planned.segments().len(),
        expected_segments.len(),
        "{label}: segment count"
    );
    for (i, segment) in expected_segments.iter().enumerate() {
        close(
            label,
            &format!("segment {i}.duration"),
            planned.segments()[i].dur,
            segment.dur,
        );
        close(
            label,
            &format!("segment {i}.jerk"),
            planned.segments()[i].jerk,
            segment.jerk,
        );
    }

    let phase_starts = expected.get("phase_starts").unwrap().as_array().unwrap();
    assert_eq!(phase_starts.len(), planned.segments().len());
    for (i, entry) in phase_starts.iter().enumerate() {
        close_state(
            label,
            &format!("phase_start {i}"),
            planned
                .phase_start(i)
                .unwrap_or_else(|| panic!("{label}: no phase start {i}")),
            read_state(entry),
        );
    }

    close_state(label, "start", planned.start(), start);
    close_state(label, "end", planned.end(), end);
}

#[track_caller]
fn check_general_case(case: &Value) {
    let label = name(case);
    let start = read_state(case.get("start").unwrap());
    let end = read_state(case.get("end").unwrap());
    let limits = read_limits_f64(case.get("limits").unwrap());
    let planned = plan_general(
        read_state_f64(case.get("start").unwrap()),
        read_state_f64(case.get("end").unwrap()),
        limits,
    )
    .unwrap_or_else(|error| panic!("{label}: general planner failed: {error:?}"));
    let expected = case.get("expected").unwrap();

    assert_eq!(
        planned.kind(),
        plan_kind(case.get("kind").unwrap().as_str().unwrap()),
        "{label}: kind"
    );
    close_state(label, "start", planned.start(), start);
    close_state(label, "end", planned.end(), end);
    close(
        label,
        "total_time",
        planned.total_time(),
        numeral_at(expected, "total_time").unwrap(),
    );

    let expected_segments = read_segments(expected.get("segments").unwrap());
    assert_eq!(
        planned.segments().len(),
        expected_segments.len(),
        "{label}: segment count"
    );
    for (i, segment) in expected_segments.iter().enumerate() {
        close(
            label,
            &format!("segment {i}.duration"),
            planned.segments()[i].dur,
            segment.dur,
        );
        close(
            label,
            &format!("segment {i}.jerk"),
            planned.segments()[i].jerk,
            segment.jerk,
        );
    }

    let phase_starts = expected.get("phase_starts").unwrap().as_array().unwrap();
    assert_eq!(phase_starts.len(), planned.segments().len());
    for (i, entry) in phase_starts.iter().enumerate() {
        close_state(
            label,
            &format!("phase_start {i}"),
            planned
                .phase_start(i)
                .unwrap_or_else(|| panic!("{label}: no phase start {i}")),
            read_state(entry),
        );
    }

    check_f64_samples(label, &planned, expected);
}

#[track_caller]
fn check_reject_case(case: &Value) {
    let label = name(case);
    let expected_error = case.get("expected_error").unwrap().as_str().unwrap();
    let limits = case.get("limits").unwrap();
    match expected_error {
        "infeasible" => {
            let target = case
                .get("target")
                .or_else(|| case.get("end"))
                .unwrap_or_else(|| panic!("{label}: no target/end state"));
            let result = plan_general(
                read_state_f64(case.get("start").unwrap()),
                read_state_f64(target),
                read_limits_f64(limits),
            );
            assert!(
                matches!(result, Err(PlanError::Infeasible)),
                "{label}: expected Infeasible, got {:?}",
                result.map(|profile| profile.kind())
            );
        }
        "non_positive_limit" => {
            let result = Limits::new(
                numeral_at(limits, "v_max").unwrap().to_f64(),
                numeral_at(limits, "a_max").unwrap().to_f64(),
                numeral_at(limits, "j_max").unwrap().to_f64(),
            );
            assert_eq!(
                result.unwrap_err(),
                PlanError::NonPositiveLimit,
                "{label}: expected NonPositiveLimit"
            );
        }
        "non_finite_input" => {
            panic!("{label}: non-finite inputs are covered by property tests, not JSON")
        }
        other => panic!("{label}: unknown expected_error {other:?}"),
    }
}

// ---------------------------------------------------------------------------
// Stretch and sync, exactly over Ratio.
// ---------------------------------------------------------------------------

#[track_caller]
fn check_stretch_case(case: &Value, cases: &[Value]) {
    let label = name(case);
    let source_name = case.get("source_case").unwrap().as_str().unwrap();
    let source = cases
        .iter()
        .find(|candidate| name(candidate) == source_name)
        .unwrap_or_else(|| panic!("{label}: source case {source_name:?} not found"));
    let factor = numeral_at(case, "factor").unwrap();
    let original = expected_profile(source);
    let stretched = original
        .stretch(factor)
        .unwrap_or_else(|error| panic!("{label}: stretch failed: {error:?}"));
    let expected = case.get("expected").unwrap();

    // The start state scales with the clock: v -> v/k, a -> a/k^2.
    assert_eq!(stretched.start().q, original.start().q, "{label}: start q");
    assert_eq!(
        stretched.start().v,
        original.start().v / factor,
        "{label}: start v"
    );
    assert_eq!(
        stretched.start().a,
        original.start().a / (factor * factor),
        "{label}: start a"
    );
    assert_eq!(
        stretched.start(),
        read_state(case.get("start").unwrap()),
        "{label}: case start state"
    );
    assert_eq!(
        stretched.end(),
        read_state(case.get("end").unwrap()),
        "{label}: end state"
    );
    assert_eq!(
        stretched.total_time(),
        numeral_at(expected, "total_time").unwrap(),
        "{label}: total time"
    );

    let expected_segments = read_segments(expected.get("segments").unwrap());
    assert_eq!(
        stretched.segments(),
        expected_segments.as_slice(),
        "{label}: segments"
    );

    let phase_starts = expected.get("phase_starts").unwrap().as_array().unwrap();
    assert_eq!(phase_starts.len(), stretched.segments().len());
    for (i, entry) in phase_starts.iter().enumerate() {
        assert_eq!(
            stretched.phase_start(i),
            Some(read_state(entry)),
            "{label}: phase start {i}"
        );
    }

    for sample in expected.get("samples").unwrap().as_array().unwrap() {
        let t = numeral_at(sample, "t").unwrap();
        let got = stretched.eval(t);
        assert_eq!(
            got.q,
            numeral_at(sample, "q").unwrap(),
            "{label}: q at {t:?}"
        );
        assert_eq!(
            got.v,
            numeral_at(sample, "v").unwrap(),
            "{label}: v at {t:?}"
        );
        assert_eq!(
            got.a,
            numeral_at(sample, "a").unwrap(),
            "{label}: a at {t:?}"
        );
    }

    let (speed, accel, jerk) = maxima(&stretched);
    assert_eq!(
        speed,
        numeral_at(expected, "max_speed").unwrap(),
        "{label}: max_speed"
    );
    assert_eq!(
        accel,
        numeral_at(expected, "max_accel").unwrap(),
        "{label}: max_accel"
    );
    assert_eq!(
        jerk,
        numeral_at(expected, "max_jerk").unwrap(),
        "{label}: max_jerk"
    );
}

#[track_caller]
fn check_sync<const N: usize>(case: &Value, profiles: &[Profile<Ratio>]) {
    let label = name(case);
    let array: [Profile<Ratio>; N] = core::array::from_fn(|i| profiles[i]);
    let synced =
        synchronize(array).unwrap_or_else(|error| panic!("{label}: synchronize failed: {error:?}"));
    let expected = case.get("expected").unwrap();
    let sync_time = numeral_at(expected, "sync_time").unwrap();
    assert_eq!(synced.total_time(), sync_time, "{label}: sync_time");

    let scales = expected.get("scales").unwrap().as_array().unwrap();
    let synchronized_segments = expected
        .get("synchronized_segments")
        .unwrap()
        .as_array()
        .unwrap();
    let phase_starts = expected.get("phase_starts").unwrap().as_array().unwrap();
    assert_eq!(scales.len(), N, "{label}: one scale per joint");
    assert_eq!(
        synchronized_segments.len(),
        N,
        "{label}: one segment list per joint"
    );
    assert_eq!(phase_starts.len(), N, "{label}: one phase list per joint");

    for i in 0..N {
        let joint = &synced.joints()[i];
        let pre = &profiles[i];
        assert_eq!(
            joint.total_time(),
            sync_time,
            "{label}: joint {i} total time"
        );

        let expected_segments = read_segments(&synchronized_segments[i]);
        assert_eq!(
            joint.segments(),
            expected_segments.as_slice(),
            "{label}: joint {i} synchronized segments"
        );

        let expected_starts = phase_starts[i].as_array().unwrap();
        assert_eq!(
            expected_starts.len(),
            joint.segments().len(),
            "{label}: joint {i} phase start count"
        );
        for (k, entry) in expected_starts.iter().enumerate() {
            assert_eq!(
                joint.phase_start(k),
                Some(read_state(entry)),
                "{label}: joint {i} phase start {k}"
            );
        }

        if scales[i].is_null() {
            // A zero-total-time joint becomes a one-segment hold for the common time.
            assert_eq!(
                pre.total_time(),
                Ratio::ZERO,
                "{label}: joint {i} stationary pre-stretch time"
            );
            assert_eq!(
                joint.segments().len(),
                1,
                "{label}: joint {i} hold has one segment"
            );
            assert_eq!(
                joint.segments()[0].jerk,
                Ratio::ZERO,
                "{label}: joint {i} hold jerk"
            );
            assert_eq!(
                joint.segments()[0].dur,
                sync_time,
                "{label}: joint {i} hold duration"
            );
            let held = State::new(pre.start().q, Ratio::ZERO, Ratio::ZERO);
            assert_eq!(joint.start(), held, "{label}: joint {i} hold start");
            assert_eq!(joint.end(), held, "{label}: joint {i} hold end");
        } else {
            let scale = numeral(&scales[i]).unwrap();
            assert_eq!(
                scale,
                sync_time / pre.total_time(),
                "{label}: joint {i} scale"
            );
            assert_eq!(
                joint.segments().len(),
                pre.segments().len(),
                "{label}: joint {i} segment count is preserved"
            );
            let scale3 = scale * scale * scale;
            for (k, segment) in pre.segments().iter().enumerate() {
                assert_eq!(
                    joint.segments()[k].dur,
                    segment.dur * scale,
                    "{label}: joint {i} segment {k} duration"
                );
                assert_eq!(
                    joint.segments()[k].jerk,
                    segment.jerk / scale3,
                    "{label}: joint {i} segment {k} jerk"
                );
            }
        }
    }

    for sample in expected.get("samples").unwrap().as_array().unwrap() {
        let t = numeral_at(sample, "t").unwrap();
        let states = sample.get("joints").unwrap().as_array().unwrap();
        assert_eq!(states.len(), N, "{label}: one state per joint");
        for (i, state_value) in states.iter().enumerate() {
            let got = synced.joints()[i].eval(t);
            let want = read_state(state_value);
            assert_eq!(got.q, want.q, "{label}: joint {i} q at t={t:?}");
            assert_eq!(got.v, want.v, "{label}: joint {i} v at t={t:?}");
            assert_eq!(got.a, want.a, "{label}: joint {i} a at t={t:?}");
        }
    }
}

#[track_caller]
fn check_sync_case(case: &Value) {
    let label = name(case);
    let joints = case.get("joints").unwrap().as_array().unwrap();
    let profiles: Vec<Profile<Ratio>> = joints
        .iter()
        .map(|joint| {
            let start = read_state(joint.get("start").unwrap());
            let segments = read_segments(joint.get("pre_stretch_segments").unwrap());
            let profile = Profile::from_parts(start, &segments).unwrap();

            // The stored pre-stretch fold must agree with the segments.
            assert_eq!(
                profile.total_time(),
                numeral_at(joint, "pre_stretch_total_time").unwrap(),
                "{label}: pre-stretch total time"
            );
            let phase_starts = joint
                .get("pre_stretch_phase_starts")
                .unwrap()
                .as_array()
                .unwrap();
            assert_eq!(
                phase_starts.len(),
                profile.segments().len(),
                "{label}: pre-stretch phase start count"
            );
            for (i, entry) in phase_starts.iter().enumerate() {
                assert_eq!(
                    profile.phase_start(i),
                    Some(read_state(entry)),
                    "{label}: pre-stretch phase start {i}"
                );
            }
            assert_eq!(
                profile.end(),
                read_state(joint.get("end").unwrap()),
                "{label}: pre-stretch end state"
            );
            profile
        })
        .collect();

    match profiles.len() {
        1 => check_sync::<1>(case, &profiles),
        2 => check_sync::<2>(case, &profiles),
        3 => check_sync::<3>(case, &profiles),
        4 => check_sync::<4>(case, &profiles),
        5 => check_sync::<5>(case, &profiles),
        6 => check_sync::<6>(case, &profiles),
        other => panic!("{label}: unsupported joint count {other}"),
    }
}

// ---------------------------------------------------------------------------
// Corpus integrity.
// ---------------------------------------------------------------------------

/// Every numeral is a JSON string; the only permitted JSON number is `schema_version`.
fn assert_all_numerals_are_strings(value: &Value, key: Option<&str>) {
    match value {
        Value::Number(number) => assert_eq!(
            key,
            Some("schema_version"),
            "JSON number at {key:?}: {number} — every motion numeral must be a string"
        ),
        Value::Array(items) => {
            for item in items {
                assert_all_numerals_are_strings(item, None);
            }
        }
        Value::Object(map) => {
            for (child_key, child) in map {
                assert_all_numerals_are_strings(child, Some(child_key));
            }
        }
        Value::Null | Value::Bool(_) | Value::String(_) => {}
    }
}

fn rational_sqrt(value: Ratio) -> Option<Ratio> {
    if value < Ratio::ZERO {
        return None;
    }
    let numerator = integer_sqrt(value.numerator());
    let denominator = integer_sqrt(value.denominator());
    if numerator * numerator == value.numerator()
        && denominator * denominator == value.denominator()
    {
        Some(Ratio::new(numerator, denominator))
    } else {
        None
    }
}

fn integer_sqrt(value: i128) -> i128 {
    if value <= 0 {
        return 0;
    }
    let mut root = (value as f64).sqrt() as i128;
    while root * root > value {
        root -= 1;
    }
    while (root + 1) * (root + 1) <= value {
        root += 1;
    }
    root
}

/// Whether an optimal rest-to-rest case sits exactly on a case boundary, where an f64
/// comparison may legitimately select the adjacent case.
fn optimal_boundary(case: &Value) -> bool {
    let start = read_state(case.get("start").unwrap());
    let end = read_state(case.get("end").unwrap());
    let limits = case.get("limits").unwrap();
    let v_max = numeral_at(limits, "v_max").unwrap();
    let a_max = numeral_at(limits, "a_max").unwrap();
    let j_max = numeral_at(limits, "j_max").unwrap();
    let d = abs(end.q - start.q);
    if d == Ratio::ZERO {
        return false;
    }
    let t_j = a_max / j_max;
    let v_a = a_max * a_max / j_max;
    if v_max == v_a {
        // `V >= v_A` decides whether the ramp reaches `a_max`; equality is exact here.
        return true;
    }
    if v_max >= v_a {
        let d_full = v_max * (t_j + v_max / a_max);
        if d == d_full {
            return true;
        }
        let b_c = Ratio::integer(2) * a_max * a_max * a_max / (j_max * j_max);
        return d < d_full && d == b_c;
    }
    // `V < v_A`: `D_full = 2 V sqrt(V/J)` is rational only when `V/J` is a square.
    match rational_sqrt(v_max / j_max) {
        Some(root) => d == Ratio::integer(2) * v_max * root,
        None => false,
    }
}

