#[test]
fn corpus_integrity() {
    let document = document();

    // Exactness contract: every motion numeral is a string.
    assert_all_numerals_are_strings(&document, None);
    assert_eq!(
        document.get("schema_version").and_then(Value::as_i64),
        Some(1),
        "schema_version is a JSON integer"
    );

    let cases = entries(&document, "cases").expect("cases");
    let mut modes = std::collections::BTreeSet::new();
    let mut kinds = std::collections::BTreeSet::new();
    let mut thresholds = 0usize;
    for case in cases {
        let label = name(case);
        let mode = case
            .get("mode")
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("{label}: missing mode"));
        let kind = case
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("{label}: missing kind"));
        modes.insert(mode);
        kinds.insert(kind);

        let threshold = case
            .get("threshold")
            .and_then(Value::as_bool)
            .unwrap_or_else(|| panic!("{label}: threshold must be a bool"));
        if threshold {
            thresholds += 1;
        }

        let segments = case
            .get("expected")
            .unwrap()
            .get("segments")
            .and_then(Value::as_array)
            .unwrap_or_else(|| panic!("{label}: missing expected segments"));
        if kind == "zero_motion" {
            assert!(
                segments.is_empty(),
                "{label}: zero motion is the empty profile"
            );
        } else if mode == "general" {
            // The general planner concatenates stop (<=4), move (7) and start (<=4).
            assert!(
                !segments.is_empty() && segments.len() <= MAX_PHASES,
                "{label}: general profile exceeds MAX_PHASES"
            );
        } else {
            assert_eq!(
                segments.len(),
                7,
                "{label}: rest-to-rest profiles use the 7-slot form"
            );
        }

        // Every exact case boundary must be marked, and every marked case must sit on
        // one. The optimal case split has three boundaries: `V = v_A`, `D = D_full(V)`
        // and `D = 2A^3/J^2`.
        if mode == "optimal" && kind != "zero_motion" {
            assert_eq!(
                threshold,
                optimal_boundary(case),
                "{label}: threshold flag must mark exact case boundaries"
            );
        }
    }

    for mode in ["conservative", "optimal", "general"] {
        assert!(modes.contains(mode), "corpus must cover mode {mode:?}");
    }
    assert_eq!(modes.len(), 3, "no unexpected mode: {modes:?}");
    for kind in [
        "zero_motion",
        "conservative",
        "cruise",
        "peak_no_cruise",
        "triangular",
        "general",
    ] {
        assert!(kinds.contains(kind), "corpus must cover kind {kind:?}");
    }
    assert_eq!(kinds.len(), 6, "no unexpected kind: {kinds:?}");
    assert!(thresholds > 0, "the corpus must mark a threshold case");

    let sync_cases = entries(&document, "sync_cases").expect("sync_cases");
    assert!(
        sync_cases.iter().any(|case| case
            .get("joints")
            .and_then(Value::as_array)
            .is_some_and(|joints| joints.len() == 6)),
        "the corpus must contain a six-joint sync case"
    );
}
